package dev.jarofcucumbers.prscraft.client;
import dev.jarofcucumbers.prscraft.*;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.components.EditBox;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.*;
import net.minecraft.network.chat.Component;
import net.neoforged.neoforge.network.PacketDistributor;
import java.util.*;
public final class SimulatorScreen extends PanelScreen{
    private final BlockPos root;private CompoundTag data;private final MapViewport view=new MapViewport();private int selected=-1,palette,wireFrom=-1;private String input="A",medium="COAXIAL",error="";private boolean environment=true,panning,dragging;private double dragX,dragY;private EditBox length,damage,dispersion;private int ticks;
    private static final String[] TYPES={"transmitter","bit_generator","message_source","message_receiver","message_codec","channel_coder","packet_sender","packet_receiver","digital_modem","amplifier","frequency_filter","modulator","adder","integrator","correlator","orthogonality_meter","time_gate","delay_line","gray_converter","drawing_board"};
    public SimulatorScreen(BlockPos root,CompoundTag data){super(Component.translatable("block.prscraft.simulator"),1000,620);this.root=root;this.data=data;view.fit(900,500,630,450);}
    public void receive(CompoundTag next){double x=0,y=0;boolean preserve=dragging&&node(selected)!=null;if(preserve){x=node(selected).getDouble("x");y=node(selected).getDouble("y");}data=next;if(preserve&&node(selected)!=null){node(selected).putDouble("x",x);node(selected).putDouble("y",y);}error=data.getString("error");}
    private void request(String action,CompoundTag tag){PacketDistributor.sendToServer(new SimulatorNetwork.Request(root,selected,action,tag));}
    private CompoundTag node(int id){var list=data.getList("nodes",10);for(int i=0;i<list.size();i++)if(list.getCompound(i).getInt("id")==id)return list.getCompound(i);return null;}
    @Override protected void build(){button(14,42,360,name(TYPES[palette]),b->{palette=(palette+1)%TYPES.length;b.setMessage(name(TYPES[palette]));});button(386,42,124,tr("sim_add"),b->{var t=new CompoundTag();t.putString("kind",TYPES[palette]);int count=data.getList("nodes",10).size();t.putDouble("x",10+(count%3)*210);t.putDouble("y",20+(count/3)*110);request("add",t);});button(522,42,124,tr("plot_auto"),b->fit());button(660,42,154,tr("sim_properties"),b->{if(node(selected)!=null){SimulationClient.node=selected;request("open",new CompoundTag());}});button(826,42,160,tr("book"),b->minecraft.setScreen(new HandbookScreen(this)));
        button(14,78,150,tr("sim_wire"),b->{if(node(selected)!=null)wireFrom=selected;});button(176,78,110,Component.literal(input),b->{input=input.equals("A")?"B":"A";b.setMessage(Component.literal(input));});button(298,78,150,tr("sim_unwire"),b->{var t=new CompoundTag();t.putString("input",input);request("unwire",t);});button(460,78,88,tr("sim_rotate"),b->request("rotate",new CompoundTag()));button(560,78,86,tr("sim_delete"),b->{request("remove",new CompoundTag());selected=-1;});button(660,78,326,tr("sim_weather_"+data.getString("weather")),b->{var choices=List.of("dry","rain","snow");var t=new CompoundTag();String weather=choices.get((choices.indexOf(data.getString("weather"))+1)%3);t.putString("weather",weather);request("weather",t);b.setMessage(tr("sim_weather_"+weather));});
        button(674,156,300,Component.literal(medium),b->{medium=medium.equals("COAXIAL")?"FIBER":medium.equals("FIBER")?"METALLIC":"COAXIAL";b.setMessage(Component.literal(medium));});length=field(674,214,300,length==null?"1":length.getValue(),18,"cable_length");damage=field(674,272,300,damage==null?"0":damage.getValue(),18,"cable_damage");dispersion=field(674,330,300,dispersion==null?"0":dispersion.getValue(),18,"dispersion");button(674,376,300,tr(environment?"sim_environment_on":"sim_environment_off"),b->{environment=!environment;b.setMessage(tr(environment?"sim_environment_on":"sim_environment_off"));});button(14,580,200,tr("back"),b->onClose());button(674,426,300,tr("sim_apply_wire"),b->{if(wireFrom>=0&&selected>=0)connect(selected);});
    }
    private Component name(String kind){return Component.translatable("block.prscraft."+kind);}
    private void connect(int target){try{var cfg=new CableSettings(number(length),number(damage)/100,number(dispersion),environment);var t=new CompoundTag();t.putInt("from",wireFrom);t.putString("input",input);t.putString("medium",medium);t.putDouble("metres",cfg.metres());t.putDouble("damage",cfg.damage());t.putDouble("dispersion",cfg.dispersion());t.putBoolean("environment",cfg.environment());int old=selected;selected=target;request("wire",t);selected=old;wireFrom=-1;error="";}catch(IllegalArgumentException e){error=e.getMessage();}}
    private void fit(){double maxX=600,maxY=350,minX=0,minY=0;var list=data.getList("nodes",10);for(int i=0;i<list.size();i++){var n=list.getCompound(i);maxX=Math.max(maxX,n.getDouble("x")+180);maxY=Math.max(maxY,n.getDouble("y")+80);minX=Math.min(minX,n.getDouble("x"));minY=Math.min(minY,n.getDouble("y"));}view.fit(maxX-minX,maxY-minY,630,440);view.pan(-minX*view.zoom(),-minY*view.zoom());}
    @Override protected void draw(GuiGraphics g){g.fill(14,126,646,564,0xff0a1420);var pose=g.pose().last().pose();var a=pose.transformPosition(14,126,0,new org.joml.Vector3f());var b=pose.transformPosition(646,564,0,new org.joml.Vector3f());g.enableScissor((int)a.x,(int)a.y,(int)b.x,(int)b.y);g.pose().pushPose();g.pose().translate(14+view.x(),126+view.y(),0);g.pose().scale((float)view.zoom(),(float)view.zoom(),1);
        var wires=data.getList("wires",10);for(int i=0;i<wires.size();i++){var w=wires.getCompound(i);var from=node(w.getInt("from"));var to=node(w.getInt("to"));if(from==null||to==null)continue;int x=(int)from.getDouble("x")+170,y=(int)from.getDouble("y")+40,tx=(int)to.getDouble("x"),ty=(int)to.getDouble("y")+(w.getString("input").equals("B")?62:25);int color=w.getString("medium").equals("FIBER")?0xff9be0f5:w.getString("medium").equals("METALLIC")?0xffd5a56b:0xff5daaaa;line(g,x,y,tx,ty,color);line(g,tx,ty,tx+8,ty-5,color);line(g,tx,ty,tx+8,ty+5,color);g.drawString(font,w.getString("input")+" · "+fmt(w.getDouble("metres"))+" m",(x+tx)/2,(y+ty)/2-12,color,false);}
        var nodes=data.getList("nodes",10);for(int i=0;i<nodes.size();i++){var n=nodes.getCompound(i);int x=(int)n.getDouble("x"),y=(int)n.getDouble("y"),id=n.getInt("id");g.fill(x,y,x+170,y+80,id==selected?0xff356a78:0xff23394c);g.fill(x,y,x+170,y+3,id==wireFrom?0xfff7cb6a:0xff6dd5aa);g.drawWordWrap(font,name(n.getString("kind")),x+8,y+12,154,0xffe0e9ea);g.drawString(font,"#"+id+" · "+n.getString("facing")+" · A/B → OUT",x+8,y+58,0xffb0cdd8,false);}
        g.pose().popPose();g.flush();g.disableScissor();label(g,"sim_wire_settings",674,130);label(g,"cable_length",674,196);label(g,"cable_damage",674,254);label(g,"dispersion",674,312);g.drawWordWrap(font,tr("sim_help"),674,466,300,0xffc6d9de);if(!error.isEmpty())g.drawWordWrap(font,Component.translatable("error.prscraft."+error),230,584,410,0xffffb07a);else g.drawString(font,"nodes="+nodes.size()+"/32 · wires="+wires.size()+"/64 · zoom="+fmt(view.zoom()),230,584,0xffa7c8d8,false);
    }
    private int hit(double x,double y){double wx=view.worldX(x-14),wy=view.worldY(y-126);var list=data.getList("nodes",10);for(int i=list.size()-1;i>=0;i--){var n=list.getCompound(i);if(wx>=n.getDouble("x")&&wx<=n.getDouble("x")+170&&wy>=n.getDouble("y")&&wy<=n.getDouble("y")+80)return n.getInt("id");}return -1;}
    @Override public boolean mouseClicked(double x,double y,int button){if(super.mouseClicked(x,y,button))return true;double lx=localX(x),ly=localY(y);if(lx<14||lx>646||ly<126||ly>564)return false;if(button==1){panning=true;return true;}if(button==0){int id=hit(lx,ly);if(id>=0){selected=id;if(wireFrom>=0&&wireFrom!=id)connect(id);else{dragging=true;var n=node(id);dragX=view.worldX(lx-14)-n.getDouble("x");dragY=view.worldY(ly-126)-n.getDouble("y");}}return true;}return false;}
    @Override public boolean mouseDragged(double x,double y,int button,double dx,double dy){if(panning){view.pan(dx/scale,dy/scale);return true;}if(dragging&&node(selected)!=null){double wx=view.worldX(localX(x)-14)-dragX,wy=view.worldY(localY(y)-126)-dragY;node(selected).putDouble("x",Math.max(-8192,Math.min(8192,wx)));node(selected).putDouble("y",Math.max(-8192,Math.min(8192,wy)));return true;}return super.mouseDragged(x,y,button,dx,dy);}
    @Override public boolean mouseReleased(double x,double y,int button){if(dragging&&node(selected)!=null){var t=new CompoundTag();t.putDouble("x",node(selected).getDouble("x"));t.putDouble("y",node(selected).getDouble("y"));request("move",t);}dragging=panning=false;return super.mouseReleased(x,y,button);}
    @Override public boolean mouseScrolled(double x,double y,double horizontal,double vertical){double lx=localX(x),ly=localY(y);if(lx>=14&&lx<=646&&ly>=126&&ly<=564){view.zoomAt(Math.pow(1.15,vertical),lx-14,ly-126);return true;}return super.mouseScrolled(x,y,horizontal,vertical);}
    @Override public void tick(){if(minecraft.player==null||minecraft.player.distanceToSqr(root.getX()+.5,root.getY()+.5,root.getZ()+.5)>64)onClose();}
    @Override public void onClose(){SimulationClient.clear();minecraft.setScreen(null);}
}
